/**
 * Agent domain types, defaults, and the field configs driving the UI.
 */

// Icon data/types are pure TS with no component imports, keeping this
// file loadable by the mock server's node-side module graph
// (vite.config / msw) — never import the AgentIcon component here.
import {
	type AgentIconName,
	ALL_AGENT_ICON_NAMES
} from '#components/agent-icons/index.ts'
import { SUPERAGENT_AGENT_ID, SUPERAGENT_NAME } from '#lib/config'

// ============================================================================
// WIRE TYPES — generated by tygo from backend/apitypes
// ============================================================================

// The wire contract lives in Go and is generated into
// #lib/types/gen/apitypes.gen (gitignored) via `just typegen` —
// regenerate, never edit. HeartbeatDuration and CronFrequency are
// literal unions there.
export type {
	ActivityPage,
	ActivityStatus,
	ActivityTrigger,
	AgentActivityItem,
	AgentEditableFields,
	CreateAgentRequest,
	CreateAgentResponse,
	CronFrequency,
	CronJob,
	ErrorResponse,
	GetAgentsResponse,
	HeartbeatConfig,
	HeartbeatDuration,
	SoulConfig,
	ThreadMessage,
	ThreadPage,
	ThreadRole
} from '#lib/types/gen/apitypes.gen'

import type {
	AgentConfig as GenAgentConfig,
	AgentConfigWithIdentity as GenAgentConfigWithIdentity,
	AgentIdentity as GenAgentIdentity,
	HeartbeatConfig,
	SoulConfig
} from '#lib/types/gen/apitypes.gen'

/**
 * Agent identity — id plus the display fields; list entries and
 * detail bodies both carry it. UI narrowing: the wire carries any
 * icon string, the UI renders only its known icon names.
 */
export interface AgentIdentity extends Omit<GenAgentIdentity, 'icon'> {
	icon: AgentIconName
}

/**
 * AgentConfig flattened from the gen embedding, with the editable
 * fields required the way a loaded config always carries them —
 * userContext stays optional (superagent-only). The gen type's
 * name/icon belong to the identity and are dropped here; cron jobs
 * are fetched separately (services/agent/cron-jobs).
 */
export type AgentConfig = Pick<GenAgentConfig, 'heartbeat'> &
	Required<
		Omit<GenAgentConfig['AgentEditableFields'], 'name' | 'icon' | 'userContext'>
	> & { userContext?: string }

/**
 * Identity (id, name, icon) plus every AgentConfig field at one
 * level — the GET/PATCH detail body, icon narrowed like
 * AgentIdentity.
 */
export type AgentConfigWithIdentity = Omit<
	GenAgentConfigWithIdentity['AgentIdentity'],
	'icon'
> &
	AgentConfig & { icon: AgentIconName }

/**
 * superagent agent definition - the primary assistant
 */
export const SUPERAGENT_AGENT: AgentIdentity = {
	id: SUPERAGENT_AGENT_ID,
	name: SUPERAGENT_NAME,
	icon: 'message-square'
}

