/**
 * Field display order for each agent type
 */
export const AGENT_FIELDS = {
	superagent: [
		'name',
		'icon',
		'soul',
		'userContext',
		'operatingInstructions',
		'toolsContext',
		'toolsEnabled',
		'heartbeat',
		'cronJobs'
	] as const,
	agent: [
		'name',
		'icon',
		'soul',
		'operatingInstructions',
		'toolsContext',
		'toolsEnabled',
		'heartbeat'
	] as const
}

/**
 * All possible configuration field names (union of all agent types)
 */
export type ConfigFieldName =
	| (typeof AGENT_FIELDS.superagent)[number]
	| (typeof AGENT_FIELDS.agent)[number]

// ============================================================================
// DEFAULT FACTORIES
// ============================================================================

/**
 * Get a random icon name
 */
function getRandomIcon(): AgentIconName {
	return ALL_AGENT_ICON_NAMES[
		Math.floor(Math.random() * ALL_AGENT_ICON_NAMES.length)
	]
}

/**
 * Create default soul configuration
 */
export function createDefaultSoulConfig(): SoulConfig {
	return {
		personality: '',
		identity: ''
	}
}

/**
 * Create the disabled heartbeat default: empty fields until a row is
 * saved (the superagent is seeded enabled).
 */
export function createDefaultHeartbeatConfig(): HeartbeatConfig {
	return {
		model: undefined,
		enabled: false,
		duration: '1hr',
		content: ''
	}
}

/**
 * Create default agent configuration — the editor's starting shape.
 * heartbeat starts disabled with empty fields.
 */
export function createDefaultAgentConfig(): AgentConfig &
	Pick<AgentIdentity, 'name' | 'icon'> {
	return {
		name: '',
		icon: getRandomIcon(),
		soul: createDefaultSoulConfig(),
		operatingInstructions: '',
		toolsContext: '',
		toolsEnabled: [],
		heartbeat: createDefaultHeartbeatConfig()
	}
}

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * Deep clone configuration object
 */
export function cloneConfiguration<T extends AgentConfig>(configuration: T): T {
	return JSON.parse(JSON.stringify(configuration))
}

/**
 * Get a configuration field value safely
 */
export function getConfigurationField(
	configuration: AgentConfig & Pick<AgentIdentity, 'name' | 'icon'>,
	field: ConfigFieldName
): unknown {
	return (configuration as unknown as Record<string, unknown>)[field]
}

/**
 * Set a configuration field value safely
 */
export function setConfigurationField(
	configuration: AgentConfig & Pick<AgentIdentity, 'name' | 'icon'>,
	field: ConfigFieldName,
	value: unknown
): void {
	;(configuration as unknown as Record<string, unknown>)[field] = value
}

/**
 * Field list for an agent type — single source of truth for rendering,
 * dirty tracking and save patches
 */
export function getAgentFields(isSuperagent: boolean) {
	return isSuperagent ? AGENT_FIELDS.superagent : AGENT_FIELDS.agent
}

/**
 * Field names whose local value differs from the saved configuration.
 * Cron jobs are excluded: they save from their own editor, never
 * through the agent config save.
 */
export function getChangedFields(
	local: AgentConfig & Pick<AgentIdentity, 'name' | 'icon'>,
	original: AgentConfig & Pick<AgentIdentity, 'name' | 'icon'>,
	isSuperagent: boolean
): ConfigFieldName[] {
	const changed: ConfigFieldName[] = []
	for (const field of getAgentFields(isSuperagent)) {
		if (field === 'cronJobs') continue
		const localValue = getConfigurationField(local, field)
		const originalValue = getConfigurationField(original, field)
		if (JSON.stringify(localValue) !== JSON.stringify(originalValue)) {
			changed.push(field)
		}
	}
	return changed
}
